/* Isolated interaction prototype. No API calls, model calls, filesystem writes or persistent app data. */
'use strict';
const $=s=>document.querySelector(s), modal=$('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const skills=['需求评审（测试）','测试分析','测试设计','文档摘要','服务巡检'];
const skillRoles={'需求评审（测试）':'测试工程师','测试分析':'测试工程师','测试设计':'测试工程师','文档摘要':'通用','服务巡检':'运维工程师'};
let currentRole='测试工程师', flowSearch='',flowFilter='全部';
const availableSkills=()=>skills.filter(n=>skillRoles[n]==='通用'||skillRoles[n]===currentRole);
const visibleFlows=()=>Object.keys(flows).filter(n=>(flowInfo[n]?.roles||['测试工程师']).some(r=>r==='通用'||r===currentRole));
const flows={'需求分析与测试设计':['需求评审（测试）','测试分析','测试设计']};
const S={now:new Date(2026,10,19,8,50),page:'workflows',ws:'HIS',detail:null,filter:'全部',search:'',seq:10,pausedApp:false,workspaces:[{id:'HIS',name:'医院信息系统',description:'围绕门诊挂号、支付与结算，与 Agent 一起推进需求和测试。',products:['HIS','移动支付'],projects:['市一院门诊升级'],knowledge:['/knowledge/HIS/需求规范','/knowledge/HIS/业务手册'],enabled:true,isDefault:true},{id:'CIS',name:'临床信息系统',description:'医嘱、临床路径与跨产品协作验证。',products:['CIS'],projects:['临床协同'],knowledge:['/knowledge/CIS'],enabled:true,isDefault:false},{id:'LIS',name:'检验信息系统',description:'管理检验业务资料与质量验证任务。',products:['LIS'],projects:[],knowledge:['/knowledge/LIS'],enabled:true,isDefault:false}],tasks:[],plans:[],history:[]};
const flowInfo={'需求分析与测试设计':{published:true,enabled:false,description:'将需求评审、测试分析与测试设计串成清晰的执行流程。',bindings:[['task'],['task','step:0'],['task','step:1']]}};
flows['测试分析与用例设计']=['测试分析','测试设计'];
flowInfo['测试分析与用例设计']={published:true,enabled:false,description:'分析测试范围和风险，再整理可执行的测试用例。',bindings:[['task'],['task','step:0']]};
const publishedFlows=()=>visibleFlows().filter(n=>flowInfo[n]?.published&&flowInfo[n]?.enabled);
let workflowDraft=null;
let draft=null, selected=new Set();
const fmt=d=>new Date(d).toLocaleString('sv-SE').slice(0,16), stamp=()=>fmt(S.now).replace(/[-:]/g,'').replace(' ','-');
const ws=id=>S.workspaces.find(w=>w.id===id), task=id=>S.tasks.find(t=>t.id===id), plan=id=>S.plans.find(p=>p.id===id);
const openTasks=id=>S.tasks.filter(t=>t.ws===id&&t.state!=='已关闭');
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3800)}
function dialog(title,body){modal.close();$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;modal.showModal()}
modal.addEventListener('cancel',e=>{if(e.target!==modal)e.stopPropagation()});
function message(t,text){t.log.push({at:fmt(S.now),text});S.history.push({at:fmt(S.now),task:t.id,text})}
function noteState(s){return ['失败','待确认'].includes(s)?'red':s==='执行中'?'':'gray'}
function badge(s){return `<span class="badge ${noteState(s)}">${esc(s)}</span>`}
function nav(page,id){S.page=page;if(page==='workspace')S.ws=id;if(page==='detail')S.detail=id;render()}
function settingsFor(label){return Object.hasOwn(flows,label)?[...flows[label]]:[label]}
function makeTask({title,ws:space='HIS',target='需求分析与测试设计',planId=null,group=null,deps=[],input=true,optional=true,confirmMode="人工确认",auto=false}){const t={id:'TASK-'+String(++S.seq).padStart(4,'0'),title,ws:space,target,steps:settingsFor(target),workflowSettings:structuredClone(flowInfo[target]||{}),bindings:structuredClone(flowInfo[target]?.bindings||[['task']]),state:'待执行',confirmMode,auto,index:0,successful:false,priority:'普通',createdAt:+S.now,input,optional,optionalDecision:false,planId,group,deps:[...deps],output:'/deliverables/'+space,files:[],archives:[],version:0,log:[],evidence:[],chat:[],issue:null,pauseRequested:false,missed:false,appointment:null};S.tasks.push(t);message(t,'创建任务；选择 '+target);return t}
function addGroup(spec,planId=null){const g='GROUP-'+(++S.seq);const defs=spec.members||[{title:'主需求 · 需求评审',target:skills[0],dep:[]},{title:'接口测试分析',target:skills[1],dep:[0]},{title:'页面测试设计',target:skills[2],dep:[0]},{title:'交付核对',target:skills[0],dep:[1,2]}];const items=[];defs.forEach((m,i)=>items.push(makeTask({title:m.title,ws:m.ws||spec.ws,target:m.target,planId,group:g,deps:m.dep.map(n=>items[n].id),input:spec.input??true,optional:spec.optional??true,confirmMode:spec.confirmMode,auto:spec.auto})));return items}
function nextTime(p,after=S.now){const start=p.start?new Date(p.start):null,end=p.end?new Date(p.end+'T23:59:59'):null;for(let i=0;i<1500;i++){const d=new Date(after);d.setDate(d.getDate()+i);const [h,m]=p.time.split(':').map(Number);d.setHours(h,m,0,0);if(d<=after||start&&d<start)continue;if(end&&d>end)return null;const wd=d.getDay();let yes=p.rule==='每天'||p.rule==='工作日'&&wd>0&&wd<6||p.rule==='每周'&&p.weekdays.includes(String(wd));if(p.rule==='每月'){const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();yes=p.day==='last'?d.getDate()===last:d.getDate()===(Number(p.day)>last&&p.monthFallback==='last'?last:Number(p.day))}if(yes)return d}return null}
function periodMembers(p){return S.tasks.filter(t=>t.planId===p.id&&t.cycle===p.cycle)}
function pendingPlan(p){return S.tasks.filter(t=>t.planId===p.id&&t.state!=='已关闭')}
function newPlan(spec){const p={id:'PLAN-'+(++S.seq),...structuredClone(spec),state:'周期进行中',cycle:0,records:[],next:null};p.next=nextTime(p);S.plans.push(p);return p}
function trigger(p,manual=false){if(p.state!=='周期进行中'||!ws(p.ws).enabled){p.records.push({at:fmt(S.now),text:'未启动：计划暂停、已到期或工作区停用'});return false}if(pendingPlan(p).length){p.records.push({at:fmt(S.now),text:'跳过本次触发：上一周期仍有未关闭执行，不积压、不补跑'});toast('上一周期尚未全部关闭，本次跳过。');return false}p.cycle++;const items=p.kind==='关联任务'?addGroup(p,p.id):[makeTask({...p,planId:p.id})];items.forEach(t=>{t.cycle=p.cycle;t.output+=`/${p.id}/cycle-${p.cycle}`});p.records.push({at:fmt(S.now),text:'创建第 '+p.cycle+' 周期，产物独立保存'});if(p.auto)items.filter(t=>!t.deps.length).forEach(t=>start(t.id,false));toast('已创建第 '+p.cycle+' 周期');return true}
function notices(){return S.tasks.filter(t=>t.state!=='已关闭'&&(t.missed||['待确认','失败','已完成'].includes(t.state)||t.issue==='interrupted')).map(t=>({task:t,title:t.title,text:t.missed?'预约时间已错过，请决定立即执行、重新预约或关闭。':t.issue==='interrupted'?'恢复结果不确定，请人工核实后继续。':t.state==='已完成'?'结果已完成，等待您验收并关闭。':t.issue==='missing'?'所需资料未齐，请统一补充或确认处理方式。':t.state==='失败'?'执行失败，请查看原因并决定重试或结束。':'本步结果需要您的确认。'}))}
function renderSidebar(){const n=notices().length;$('#sidebar').innerHTML=`<div class="brand"><img src="assets/logo.svg" alt="OmniAlba"></div><div class="nav-label">工作台</div><button class="nav ${S.page==='tasks'?'active':''}" data-icon="▤" onclick="nav('tasks')"><span>▤　我的任务</span><span>${n}</span></button><button class="nav ${S.page==='workspaces'?'active':''}" data-icon="▦" onclick="nav('workspaces')"><span>▦　工作区</span><span>⌄</span></button>${S.workspaces.map(w=>`<button class="nav subnav ${S.page==='workspace'&&S.ws===w.id?'active':''}" data-icon="□" onclick="nav('workspace','${w.id}')"><span>${esc(w.code||w.id)}　${esc(w.name)}</span><span>›</span></button>`).join('')}<div class="nav-label">工具</div><button class="nav" data-icon="◇" onclick="showResources()"><span>◇　技能中心</span></button><button class="nav ${S.page==='workflows'?'active':''}" data-icon="⑂" onclick="showFlows()"><span>⑂　工作流</span></button><div class="sidebar-bottom">设计评审账户<small style="display:block">仅演示数据 · 刷新恢复初始场景</small></div>`;$('#bell').textContent='待处理 '+n}
function stats(items){return `<div class="counts">${['执行中','待确认','失败'].map(s=>`<div class="count"><div>${s}<b>${items.filter(t=>t.state===s).length}</b></div><small>${S.workspaces.map(w=>(w.code||w.id)+' '+items.filter(t=>t.ws===w.id&&t.state===s).length).join(' · ')}</small></div>`).join('')}</div>`}
function row(t,selectable=false){return `<div class="task-row">${selectable?`<input type="checkbox" aria-label="选择 ${esc(t.title)}" ${selected.has(t.id)?'checked':''} onchange="toggleSelected('${t.id}',this.checked)">`:''}<div class="task-copy"><button class="open-task" onclick="nav('detail','${t.id}')"><strong>${esc(t.title)}</strong></button><small>${esc(t.id)} · ${esc(t.target)}${t.group?' · 关联成员':''}${t.planId?' · 第'+t.cycle+'周期':''} · ${esc(t.priority)}</small></div>${badge(t.state)}<button class="quiet" onclick="nav('detail','${t.id}')">查看 ›</button></div>`}
function pageTasks(){const active=S.tasks.filter(t=>t.state!=='已关闭');let list=S.tasks.filter(t=>(S.filter==='全部'||t.state===S.filter)&&(!S.search||t.title.includes(S.search)||t.id.includes(S.search)));list.sort((a,b)=>({'高':0,'普通':1,'低':2}[a.priority]-{'高':0,'普通':1,'低':2}[b.priority])||b.createdAt-a.createdAt);return `<div class="page-head"><div><span class="eyebrow">MY TASKS</span><h1>我的任务</h1><p>把注意力留给你需要推进的工作。</p></div>${stats(active)}</div><div class="assistant"><div class="avatar">◌</div><div class="bubble"><div class="assistant-name">OmniAlba · 任务提醒</div><p>${notices().length?'今天也一起稳步推进吧，还有 <b>'+notices().length+'</b> 项工作需要您的协助。':'太棒了，目前没有需要您介入处理的任务。'}</p>${notices().slice(0,4).map(n=>`<div class="task-row"><span class="ws-flag">${n.task.ws}</span><div class="task-copy"><strong>${esc(n.title)}</strong><small>${esc(n.text)}</small></div><button class="quiet" onclick="nav('detail','${n.task.id}')">去处理 ›</button></div>`).join('')}</div></div><div class="toolbar"><input class="search" placeholder="搜索任务名称或标识…" value="${esc(S.search)}" onchange="S.search=this.value;render()"><button onclick="batchClose()">关闭所选 (${selected.size})</button><button class="primary" onclick="createTask()">＋ 新任务</button></div><div class="tabs">${['全部','待执行','执行中','待确认','已暂停','失败','已完成','已关闭'].map(f=>`<button class="${S.filter===f?'active':''}" onclick="S.filter='${f}';render()">${f}</button>`).join('')}</div><div class="section-label">任务与执行</div><div class="panel">${list.length?list.map(t=>row(t,true)).join(''):'<div class="empty">暂无此状态的任务。</div>'}</div><div class="section-label">周期任务</div>${S.plans.map(planCard).join('')}`}
function planCard(p){const pending=pendingPlan(p);return `<div class="plan-card"><div class="plan-head"><div><h3>${esc(p.title)} ${badge(p.state)}</h3><small>${p.ws} · ${p.rule} ${p.time} · 下次：${p.state==='周期进行中'&&p.next?fmt(p.next):'不再调度'} · ${pending.length} 项执行未关闭</small></div><button onclick="showPlan('${p.id}')">管理周期 ›</button></div><div class="plan-children">${S.tasks.filter(t=>t.planId===p.id).map(t=>row(t)).join('')||'<small>尚未产生执行子任务，计划本身不锁定技能或工作区。</small>'}</div></div>`}
function pageWorkspaces(){return `<div class="page-head"><div><span class="eyebrow">WORKSPACES</span><h1>我的工作区</h1><p>双击卡片进入您的工作区，与 Agent 一起推进任务。</p></div><button class="primary" onclick="editWorkspace()">＋ 新建工作区</button></div><div class="workspace-grid">${S.workspaces.map(w=>{const pending=openTasks(w.id);return `<article class="workspace-card" ondblclick="nav('workspace','${w.id}')"><header><div class="workspace-icon">${esc(w.code||w.id)}</div><div><div class="workspace-code">${esc(w.code||w.id)}</div><h2>${esc(w.name)}</h2></div>${badge(w.enabled?'已启用':'已停用')}</header><p title="${esc(w.description)}">${esc(w.description)}</p><div class="tags">${[...w.products,...w.projects].map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><div class="knowledge">▱ ${w.knowledge.map(esc).join('<br>▱ ')||'尚无知识来源'}</div><div class="default-label">${w.isDefault?'☆ 默认工作区':'☆ 非默认工作区'}</div><div class="card-stats"><span>独立任务 <b>${pending.filter(t=>!t.group).length}</b></span><span>关联任务 <b>${pending.filter(t=>t.group).length}</b></span></div><div class="card-actions"><button onclick="event.stopPropagation();nav('workspace','${w.id}')">打开 ›</button><button ${pending.length?'disabled':''} title="${pending.length?'未关闭实际任务会锁定编辑':'编辑工作区'}" onclick="editWorkspace('${w.id}')">编辑</button><button ${pending.length?'disabled':''} onclick="toggleWorkspace('${w.id}')">${w.enabled?'停用':'启用'}</button></div>${pending.length?'<small>未关闭执行保护中；周期计划本身不额外锁定。</small>':''}</article>`}).join('')}</div>`}
function pageWorkspace(){const w=ws(S.ws),items=S.tasks.filter(t=>t.ws===w.id&&t.state!=='已关闭');return `<div class="workspace-view"><div class="page-head"><div><span class="eyebrow">WORKSPACE</span><h1><span class="ws-flag">${esc(w.code||w.id)}</span> ${esc(w.name)}</h1><p>${esc(w.description)}</p></div><button class="primary" ${!w.enabled?'disabled':''} onclick="createTask('${w.id}')">＋ 新任务</button></div>${!w.enabled?'<div class="notice">此工作区已停用，预约及周期暂停调度；恢复后不补跑。</div>':''}<div class="assistant"><div class="avatar">◌</div><div class="bubble"><div class="assistant-name">OmniAlba · 工作区助手</div><p>欢迎回来。把资料准备好，我们一起推进今天的工作。</p><div class="tags">${w.knowledge.map(x=>`<span class="tag">▱ ${esc(x)}</span>`).join('')}</div>${items.length?items.map(t=>row(t)).join(''):'<div class="empty">没有未关闭的执行，您可以维护工作区配置。</div>'}${S.plans.filter(p=>p.ws===w.id).map(planCard).join('')}${workspaceChatMarkup(w.id)}</div></div><form class="composer" onsubmit="event.preventDefault();draftFromChat(this.message.value)"><textarea name="message" placeholder="告诉 OmniAlba 你想完成什么？你也可以点击「新任务」开始…" required></textarea><button type="submit" class="primary">发送</button></form></div>`}
function render(){$('.app').dataset.section=['workflows','flowedit'].includes(S.page)?'workflows':'tasks';$('#main').dataset.page=S.page;renderSidebar();$('#crumb').textContent=S.page==='workflows'?'个人工作空间 / 工作流':S.page==='detail'?'个人工作空间 / '+task(S.detail).ws+' / '+task(S.detail).title:S.page==='workspace'?'个人工作空间 / '+S.ws:S.page==='workspaces'?'个人工作空间 / 工作区':'个人工作空间 / 我的任务';$('#main').innerHTML=S.page==='flowedit'?flowEditorMarkup():S.page==='workflows'?pageFlows():S.page==='tasks'?pageTasks():S.page==='workspaces'?pageWorkspaces():S.page==='workspace'?pageWorkspace():pageDetail()}
const workspaceChats={};
function workspaceChatMarkup(id){return (workspaceChats[id]||[]).map((m,i)=>m.proposal?`<section class="panel" style="margin-top:12px"><b>任务已整理 · 待确认</b><form onsubmit="event.preventDefault();confirmChatProposal('${id}',${i},this)"><label class="field">任务名称<input name="title" value="${esc(m.proposal.title)}" required></label><div class="form-grid"><label class="field">执行方式<select name="period"><option ${m.proposal.period?'selected':''}>每天</option><option ${!m.proposal.period?'selected':''}>人工启动</option></select></label><label class="field">时间<input type="time" name="time" value="${m.proposal.time}" required></label><label class="field full">执行技能或工作流<select name="target" required><option value="">请选择适合此工作的技能或已启用工作流</option>${[...availableSkills(),...publishedFlows()].map(v=>`<option>${esc(v)}</option>`).join('')}</select></label><label class="field full">收件邮箱（如需发送）<input name="email" type="email" value="${esc(m.proposal.email)}" placeholder="请补全正确的邮箱地址"></label></div><p class="notice">${m.proposal.mail?'已识别邮件要求，但本 Demo 不发送邮件；请补全邮箱，并选择具备日报与邮件能力的技能。':'请核对执行内容，确认后创建，不会立即启动。'}${m.proposal.badEmail?' 原输入中的邮箱不完整。':''}</p><button class="primary">确认创建任务</button></form></section>`:`<div class="chat-line ${m.who}" style="margin-top:10px">${esc(m.text)}</div>`).join('')}
function draftFromChat(text){text=text.trim();if(!text)return;const id=S.ws,chat=workspaceChats[id]||(workspaceChats[id]=[]);chat.push({who:'user',text});if(/新建|创建|安排|定时|周期任务/.test(text)){const time=text.match(/([01]?\d|2[0-3])[:：]([0-5]\d)/),email=text.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);chat.push({who:'assistant',text:'已根据您的要求整理任务，您可以直接在下方修改并确认；缺少的信息需要补齐。'});chat.push({proposal:{title:/日报/.test(text)?'每日工作日报':text.slice(0,50),period:/每日|每天|周期/.test(text),time:time?time[1].padStart(2,'0')+':'+time[2]:'17:00',mail:/邮件|邮箱|@/.test(text),email:email?email[0]:'',badEmail:/@/.test(text)&&!email,description:text}})}else{let answer=/任务|进度|待办/.test(text)?'当前工作区有 '+openTasks(id).length+' 个未关闭任务。您可以告诉我想查看哪个任务，或说明下一步要完成的工作。':/如何|怎么|帮助/.test(text)?'您可以让我整理工作思路、分析您提供的内容、查看当前任务，或用自然语言安排任务。例如：每天17:00整理工作日报。':'已收到您的内容。您希望我帮助整理要点、分析问题，还是安排后续任务？本 Demo 使用规则演示反馈，不调用真实模型。';chat.push({who:'assistant',text:answer})}render()}
function confirmChatProposal(id,i,f){const p=workspaceChats[id][i].proposal;if(!p||!f.reportValidity())return;if(!f.elements['target'].value)return toast('请选择执行技能或工作流。');if(p.mail&&!f.elements['email'].value)return toast('邮件地址不完整，请补充。');const spec={title:f.elements['title'].value,ws:id,target:f.elements['target'].value,input:false,optional:true,description:p.description};if(f.elements['period'].value==='每天')newPlan({...spec,kind:'独立任务',auto:true,rule:'每天',time:f.elements['time'].value,start:fmt(S.now).replace(' ','T'),end:'',weekdays:['1'],day:'1',monthFallback:'skip'});else makeTask(spec);workspaceChats[id][i]={who:'assistant',text:'已创建「'+f.elements['title'].value+'」。可在上方查看和修改；实际资料待补齐，邮件不会由本 Demo 发送。'};render();toast('任务已创建，未立即执行。')}

function createTask(space=S.ws,title=''){draft={ws:space,title,kind:'独立任务',execution:'非周期',trigger:'人工',confirmMode:'人工确认',targetType:publishedFlows().length?'工作流':'技能',target:publishedFlows()[0]||availableSkills()[0],description:'',input:true,optional:true,rule:'每天',time:'09:00',start:fmt(S.now).replace(' ','T'),end:'',day:'1',weekdays:['1'],monthFallback:'skip',members:null};taskForm()}
function taskForm(){const d=draft;dialog('新建任务',`<form id="task-form" onsubmit="event.preventDefault();previewTask()"><div class="field-error" id="form-error" role="alert"></div><div class="form-grid"><label class="field full">任务名称 *<input name="title" value="${esc(d.title)}" required></label><label class="field">工作区<select name="ws">${S.workspaces.filter(w=>w.enabled).map(w=>`<option value="${w.id}" ${d.ws===w.id?'selected':''}>${esc(w.code||w.id)} · ${esc(w.name)}</option>`).join('')}</select></label><label class="field">任务类型<select name="kind" onchange="readDraft();taskForm()">${['独立任务','关联任务'].map(x=>`<option ${d.kind===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">执行类型<select name="execution" onchange="readDraft();taskForm()">${['非周期','周期'].map(x=>`<option ${d.execution===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">触发方式<select name="trigger" onchange="readDraft();taskForm()">${['人工','自动'].map(x=>`<option ${d.trigger===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field full">步骤确认方式<select name="confirmMode">${['人工确认','自动继续'].map(x=>`<option ${d.confirmMode===x?'selected':''}>${x}</option>`).join('')}</select><small>资料缺失仍需统一处理；全部执行完成后仍需人工关闭。</small></label><div class="full"><div class="form-section">执行内容 · 一个技能或一个工作流</div><div class="choice"><label><input type="radio" name="targetType" value="技能" ${d.targetType==='技能'?'checked':''} onchange="readDraft();draft.target=availableSkills()[0];taskForm()"> 技能</label><label><input type="radio" name="targetType" value="工作流" ${d.targetType==='工作流'?'checked':''} onchange="readDraft();draft.target=publishedFlows()[0];taskForm()"> 工作流</label></div></div><label class="field full">${d.targetType}<select name="target" required>${d.targetType==='工作流'&&!publishedFlows().length?'<option value="">暂无已启用工作流，请先配置并启用</option>':''}${(d.targetType==='技能'?availableSkills():publishedFlows()).map(x=>`<option ${d.target===x?'selected':''}>${x}</option>`).join('')}</select><small>每个任务只选一个；工作流已由人编排，Demo 不自动判断业务串接。</small></label>${d.kind==='关联任务'?`<div class="full"><div class="form-section">关联成员 · 周期与触发只在主任务配置</div><div class="notice">演示混合关系：A 完成后 B、C 可并行；D 等待 B、C 完成。各任务只读取明确登记的共享资料，不自动交换彼此产物。</div>${[0,1,2,3].map((i)=>`<div class="group-line"><span>${'ABCD'[i]} · ${['主任务','关联成员','关联成员','关联成员'][i]}</span><input name="member${i}" aria-label="成员${i}名称" value="${esc(d.members?.[i]?.title||['需求评审','接口测试分析','页面测试设计','交付核对'][i])}"><select name="memberTarget${i}">${[...availableSkills(),...publishedFlows()].map(x=>`<option ${x===(d.members?.[i]?.target||[d.target,skills[1],skills[2],skills[0]][i])?'selected':''}>${x}</option>`).join('')}</select><select name="deps${i}" aria-label="成员${i}前置">${(i===0?[['','无']]:[['','无'],...Array.from({length:i},(_,n)=>[String(n),'等待 '+'ABCD'[n]]),...(i>2?[['1,2','等待 B 和 C']]:[])]).map(([v,l])=>`<option value="${v}" ${v===(d.members?.[i]?.dep?.join(',')??['','0','0','1,2'][i])?'selected':''}>${l}</option>`).join('')}</select></div>`).join('')}</div>`:''}${d.execution==='周期'?`<div class="full form-section">周期计划</div><label class="field">重复规则<select name="rule" onchange="readDraft();taskForm()">${['每天','每周','工作日','每月'].map(x=>`<option ${d.rule===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">时间<input type="time" name="time" value="${d.time}" required></label>${d.rule==='工作日'?'<small class="full">工作日按周一至周五，不自动推算法定节假日与调休。</small>':''}${d.rule==='每周'?`<div class="choice full">${['日','一','二','三','四','五','六'].map((x,i)=>`<label><input type="checkbox" name="weekdays" value="${i}" ${d.weekdays.includes(String(i))?'checked':''}>周${x}</label>`).join('')}</div>`:''}${d.rule==='每月'?`<label class="field">日期<select name="day">${[...Array.from({length:31},(_,i)=>String(i+1)),'last'].map(x=>`<option value="${x}" ${d.day===x?'selected':''}>${x==='last'?'最后一天':x+'日'}</option>`).join('')}</select></label><label class="field">该月没有此日期<select name="monthFallback"><option value="skip" ${d.monthFallback==='skip'?'selected':''}>跳过当月</option><option value="last" ${d.monthFallback==='last'?'selected':''}>当月最后一天</option></select></label>`:''}<label class="field">开始时间<input type="datetime-local" name="start" value="${d.start}" required></label><label class="field">截止日期（可选）<input type="date" name="end" value="${d.end}"></label>`:d.trigger==='自动'?`<label class="field full">预约时间 *<input type="datetime-local" name="appointment" value="${d.appointment||fmt(new Date(+S.now+3600000)).replace(' ','T')}" required></label>`:''}<label class="field full">工作目标与说明<textarea name="description">${esc(d.description)}</textarea></label><div class="full materials"><div class="form-section">本次资料 · Demo 用就绪状态演示，不读取正式文件</div><label><input type="checkbox" name="input" ${d.input?'checked':''}> 必需：需求资料已提供<small>包含目标、业务流程与规则；缺失时不能开始。</small></label><label><input type="checkbox" name="optional" ${d.optional?'checked':''}> 可选：原型已提供<small>缺失时由您统一决定是否仅评审文字，不检查界面一致性。</small></label></div></div><div class="form-footer"><button type="button" onclick="modal.close()">取消</button><button class="primary">下一步 · 预览</button></div></form>`)}
function readDraft(){const f=$('#task-form');if(!f)return;const d=new FormData(f);for(const k of ['title','ws','kind','execution','trigger','targetType','target','description','rule','time','start','end','day','monthFallback','appointment','confirmMode'])if(d.has(k))draft[k]=d.get(k);draft.input=d.has('input');draft.optional=d.has('optional');if(draft.rule==='每周')draft.weekdays=d.getAll('weekdays');if(d.has('member0'))draft.members=[0,1,2,3].map(i=>({title:d.get('member'+i)||'关联任务',target:d.get('memberTarget'+i),dep:String(d.get('deps'+i)||'').split(',').filter(Boolean).map(Number)}))}
function previewTask(){readDraft();if(draft.kind==='关联任务'&&draft.members)draft.members[0].target=draft.target;if(!draft.title.trim())return $('#form-error').textContent='请填写任务名称。';if(draft.execution==='周期'&&draft.rule==='每周'&&!draft.weekdays.length)return $('#form-error').textContent='请选择至少一个星期。';if(draft.execution==='周期'&&draft.end&&new Date(draft.end+'T23:59:59')<new Date(draft.start))return $('#form-error').textContent='截止日期不能早于开始日期。';dialog('确认创建任务',`<div class="notice">预览不执行任务，也不调用模型。缺失资料会在实际启动前统一处理。</div>${[['任务',draft.title],['归属',draft.ws],['结构',draft.kind+' · '+draft.execution],['启动',draft.trigger==='人工'?'人工启动':draft.execution==='周期'?draft.rule+' '+draft.time:draft.appointment],['执行',draft.targetType+' · '+draft.target],['步骤确认',draft.confirmMode],['输入',draft.input?'需求资料已就绪':'缺少必需需求资料'],['可选资料',draft.optional?'原型已就绪':'未提供原型，需统一确认处理'],['模型','使用技能／工作流默认配置（演示）'],['交付位置','/deliverables/'+draft.ws],['Knowledge',ws(draft.ws).knowledge.join('；')]].map(([l,v])=>`<div class="preview-row"><span>${l}</span><b>${esc(v)}</b></div>`).join('')}<div class="form-footer"><button onclick="taskForm()">上一步</button><button class="primary" onclick="commitTask()">确认创建</button></div>`)}
function commitTask(){if(!ws(draft.ws).enabled)return toast('工作区已停用。');const spec={...structuredClone(draft),auto:draft.trigger==='自动'};if(draft.execution==='周期'){newPlan(spec);toast('周期计划已创建；尚无执行，不锁定资源。')}else{const items=draft.kind==='关联任务'?addGroup(spec):[makeTask(spec)];items.forEach(t=>{t.description=draft.description;t.auto=spec.auto;if(draft.trigger==='自动')t.appointment=new Date(draft.appointment)});toast('任务已创建')}modal.close();nav('tasks')}
function start(id,redraw=true){const t=task(id);if(!t||!['待执行','已暂停','失败','待确认'].includes(t.state))return;if(Object.hasOwn(flows,t.target)&&!flowInfo[t.target]?.enabled)return toast('工作流尚未启用，请先启用。');if(!ws(t.ws).enabled)return toast('工作区已停用，不能启动。');if(t.deps.some(d=>!task(d).successful))return toast('必要前置尚未完成，不能启动。');if(t.appointment&&t.appointment>S.now&&!t.missed)return toast('尚未到预约时间。');if(t.issue==='interrupted')return toast('请先人工核实中断结果。');if(!t.input||!t.optional&&!t.optionalDecision){t.state='待确认';t.issue='missing';message(t,'统一检查资料：等待补充或人工决定');if(redraw)render();return}if(t.issue==='approval')return toast('请确认本步结果，不必重新执行。');t.state='执行中';t.issue=null;t.missed=false;t.pauseRequested=false;t.evidence.push({at:fmt(S.now),source:'任务需求资料 + '+ws(t.ws).knowledge.join('；'),summary:'本次演示登记实际使用来源；不读取本机真实文件'});message(t,'开始 '+t.steps[t.index]+'；前置及资料检查通过');if(redraw)render()}
function finishStep(id,outcome='success'){const t=task(id);if(t.state!=='执行中')return toast('请先启动执行。');if(outcome==='failure'){t.state='失败';t.issue='failure';message(t,'当前步骤执行失败（演示）：模型服务连接中断，等待人工决定');render();return}if(outcome==='missing'){t.state='待确认';t.issue='missing';t.input=false;message(t,'读取时发现必需信息不足；停止后续处理');render();return}const name=t.steps[t.index]+'_'+t.id+'.md';t.files=t.files.filter(f=>f.step!==t.index);t.files.push({name,step:t.index,content:'# '+t.steps[t.index]+'\n\n本文件仅用于演示产物归属和保留逻辑，不代表真实模型结果。\n任务：'+t.title+'\n执行：'+(t.cycle||1)+'\n生成时间：'+fmt(S.now)});t.state='待确认';t.issue='approval';if((t.workflowSettings?.settings?.[t.index]?.confirm==='使用工作流设置'?(t.workflowSettings.defaultConfirmation||t.confirmMode):(t.workflowSettings?.settings?.[t.index]?.confirm||t.confirmMode))==='自动继续'){approve(id);return}message(t,'本步演示结果已生成，等待人工确认；业务疑点本身不会自动阻塞');render()}
function approve(id){const t=task(id);if(t.issue!=='approval')return;message(t,t.confirmMode==='自动继续'?'本步成功，按配置继续；不重复执行':'人工确认通过，不重复执行本步');t.index++;t.issue=null;if(t.index>=t.steps.length){t.state='已完成';t.successful=true;message(t,'全部步骤完成；仍需人工关闭，引用锁未释放')}else if(t.pauseRequested){t.state='已暂停';t.pauseRequested=false;message(t,'到达安全点，暂停后续步骤')}else{t.state='待执行';start(t.id,false)}if(t.successful&&t.group)S.tasks.filter(x=>x.group===t.group&&x.auto&&x.state==='待执行'&&x.deps.every(d=>task(d).successful)).forEach(x=>start(x.id,false));render()}
function requestPause(id){const t=task(id);if(t.state==='执行中'){t.pauseRequested=true;message(t,'已登记暂停请求；不会中断当前步骤');toast('暂停请求已提交，当前步骤结束后处理。')}else if(t.state!=='已关闭'&&t.state!=='已完成'){t.state='已暂停';message(t,'暂停执行')}render()}
function materials(id){const t=task(id);dialog('统一检查与补充资料',`<form onsubmit="event.preventDefault();saveMaterials('${id}',this)"><div class="notice">必需资料缺失不能绕过；可选资料一次确认。新增资料不隐式改写正在执行的步骤。</div><div class="materials"><label><input name="required" type="checkbox" ${t.input?'checked':''}> 必需：需求资料及必要业务规则<small>缺失会阻止执行，请补齐。</small></label><label><input name="optional" type="checkbox" ${t.optional?'checked':''}> 可选：页面原型<small>未提供时只分析文字规则，结果注明本次未核对原型。</small></label><label><input name="accept" type="checkbox" ${t.optionalDecision?'checked':''}> 已了解影响，同意在未提供原型时仅处理文字内容</label></div><div id="materials-error" class="field-error"></div><div class="form-footer"><button type="button" onclick="modal.close()">取消</button><button class="primary">保存处理决定</button></div></form>`)}
function saveMaterials(id,f){const t=task(id);if(t.state==='执行中'||t.state==='已关闭')return toast('当前状态不能改写本次输入。');if(!f.required.checked)return $('#materials-error').textContent='缺少必需需求资料，不能继续。';if(!f.optional.checked&&!f.accept.checked)return $('#materials-error').textContent='请统一确认缺少原型的处理方式。';t.input=true;t.optional=f.optional.checked;t.optionalDecision=f.accept.checked;if(t.issue==='missing'){t.state='待执行';t.issue=null}message(t,'人工补齐／确认输入处理；待手动继续本步');modal.close();render()}
function affected(t){const ids=new Set([t.id]);let changed=true;while(changed){changed=false;for(const x of S.tasks)if(x.group&&x.group===t.group&&!ids.has(x.id)&&x.deps.some(d=>ids.has(d))){ids.add(x.id);changed=true}}return [...ids].map(task)}
function rerun(id){const t=task(id),items=affected(t);if(t.state==='已关闭')return toast('已关闭任务只读，可复制为新任务。');dialog('重新执行',`<div class="notice">只影响本次执行所选步骤及依赖后续；前序和独立分支保留。执行历史始终保留。</div><label class="field">从哪一步开始<select id="rerun-step">${t.steps.map((s,i)=>i<=Math.min(t.index,t.steps.length-1)?`<option value="${i}" ${i===Math.min(t.index,t.steps.length-1)?'selected':''}>${i+1}. ${s}</option>`:'').join('')}</select></label><label class="choice"><input id="keep-results" type="checkbox" checked> 保留上次结果（自动版本号＋分钟时间戳）</label><small>取消勾选将清除本次重跑范围的当前旧结果，不影响原始输入、其他周期或无关文件。</small><div class="section-label">受影响任务</div>${items.map(x=>`<div class="preview-row"><span>${esc(x.title)}</span>${badge(x.state)}</div>`).join('')}<div class="form-footer"><button onclick="modal.close()">取消</button><button class="primary" onclick="commitRerun('${id}')">确认重跑</button></div>`)}
function commitRerun(id){const t=task(id),items=affected(t);if(items.some(x=>x.state==='执行中'||x.state==='已关闭')){toast('受影响任务正在执行或已关闭，请先人工处理；当前结果未改动。');return}if(items.some(x=>!ws(x.ws).enabled||!x.input||!x.optional&&!x.optionalDecision)){toast('请先处理工作区或资料问题；当前结果未改动。');return}const from=Number($('#rerun-step').value),keep=$('#keep-results').checked;for(const x of items){const n=x.id===id?from:0;const old=x.files.filter(f=>f.step>=n);if(keep&&old.length){x.version++;x.archives.push(...old.map(f=>({...f,name:f.name.replace(/\.([^.]+)$/,`_v${x.version}_${stamp()}.$1`),at:fmt(S.now)})))}x.files=x.files.filter(f=>f.step<n);x.index=n;x.state='待执行';x.successful=false;x.issue=null;x.pauseRequested=false;message(x,'人工从第'+(n+1)+'步重跑；'+(keep?'旧结果已保留并标记版本／分钟时间戳':'不保留本次范围旧结果')+'；历史记录保留');if(n>0)x.evidence.push({at:fmt(S.now),source:'保留前序输出',summary:'本次重新读取前序结果留证'})}modal.close();render();toast('重跑范围已处理，等待启动；独立分支保持不变。')}
function closeTasks(ids){const items=ids.map(task).filter(Boolean);dialog('关闭任务 · 确认范围',`<p>关闭是最终状态，关闭后只读。完成、失败和放弃按真实情况分别记录。</p>${items.map(t=>`<div class="preview-row"><span>${esc(t.title)}</span>${badge(t.state)}</div>`).join('')}<label class="field">关闭说明<textarea id="close-reason" placeholder="说明本次验收或结束原因" required></textarea></label><div class="notice">执行中的步骤不能直接关闭。关闭失败任务只表示人工放弃，不会放行其依赖后置。</div><div class="form-footer"><button onclick="modal.close()">取消</button><button class="primary" onclick='commitClose(${JSON.stringify(ids)})'>确认关闭所选</button></div>`)}
function commitClose(ids){const items=ids.map(task);if(items.some(t=>t.state==='执行中'))return toast('请先请求安全暂停并处理当前步骤，未关闭任何任务。');const reason=$('#close-reason').value.trim();if(!reason)return toast('请填写关闭说明。');for(const t of items){if(t.state==='已关闭')continue;t.state='已关闭';t.issue=null;message(t,(t.successful?'正常完成':t.log.some(x=>x.text.includes('失败'))?'失败后放弃':'主动取消')+' · '+reason)}selected.clear();modal.close();render();toast('所选任务已关闭；仅解除其实际执行引用。')}
function toggleSelected(id,value){value?selected.add(id):selected.delete(id)}
function batchClose(){const ids=[...selected].filter(id=>task(id).state!=='已关闭');if(!ids.length)return toast('请先选择要收尾的任务。');closeTasks(ids)}
function downloadResult(id,index,archive=false){const t=task(id),file=(archive?t.archives:t.files)[index];const a=document.createElement('a');const url=URL.createObjectURL(new Blob([file.content],{type:'text/markdown;charset=utf-8'}));a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function pageDetail(){const t=task(S.detail);const locked=t.state==='已关闭';const missing=t.issue==='missing';const dependencies=t.deps.map(task);return `<div class="detail-head"><button class="quiet" onclick="nav('tasks')">‹ 返回</button><div><h1>${esc(t.title)}</h1><small><span class="ws-flag">${t.ws}</span> 任务编号：${t.id} · 测试用例编号示例：${t.id}-TC-001 · ${t.planId?'周期子任务 · 第'+t.cycle+'周期':'非周期任务'} · ${esc(t.target)}</small></div>${badge(t.state)}<select style="width:100px" aria-label="任务优先级" ${['执行中','已关闭'].includes(t.state)?'disabled':''} onchange="task('${t.id}').priority=this.value;render()">${['低','普通','高','紧急'].map(x=>`<option ${x===t.priority?'selected':''}>${x}</option>`).join('')}</select></div>${dependencies.length?`<div class="notice">前置：${dependencies.map(x=>esc(x.title)+'（'+x.state+'）').join('、')}。以前置完成放行，不要求先关闭；失败或放弃不算成功。</div>`:''}${t.missed?'<div class="notice error">预约时间已错过，未自动补执行。请选择人工立即执行、重新预约或关闭。</div>':''}${t.issue==='interrupted'?'<div class="notice error">后台恢复不确定：请核实当前步骤是否已产生外部影响，再决定从哪一步继续。</div>':''}${missing?'<div class="notice error">⚠ 必需资料或可选资料处理尚未齐备，请统一处理，不能猜测继续。</div>':''}${t.issue==='failure'?'<div class="notice error">⚠ 本步失败：模型服务连接中断（演示）。由人决定重试或关闭，不自动修复技能或解除锁。</div>':''}<div class="actions">${locked?'<span class="muted">已关闭，只读查看；历史和产物保留。</span>':`${t.issue==='approval'?`<button class="primary" onclick="approve('${t.id}')">确认本步结果</button>`:`<button class="primary" ${t.state==='执行中'||t.state==='已完成'||dependencies.some(x=>!x.successful)?'disabled':''} onclick="start('${t.id}')">${t.state==='待执行'?'启动执行':'继续本步'}</button>`}<button ${t.state==='已完成'?'disabled':''} onclick="requestPause('${t.id}')">${t.pauseRequested?'已请求安全暂停':'暂停执行'}</button><button onclick="rerun('${t.id}')">选择步骤重跑</button><button ${t.state==='执行中'?'disabled':''} onclick="materials('${t.id}')">资料处理</button><button onclick="closeTasks(['${t.id}'])">关闭任务</button>${t.missed?`<button onclick="reschedule('${t.id}')">重新预约</button>`:''}${t.issue==='interrupted'?`<button onclick="ackRecovery('${t.id}')">核实后重试本步</button>`:''}`}</div><div class="detail-grid" style="margin-top:20px"><div class="detail-main"><section class="panel"><h3>任务协助</h3><div class="detail-chat"><div class="chat-line">${locked?'本次执行已经关闭，您可以查看记录和交付内容。':t.issue==='approval'?'本步结果已就绪。确认通过将进入下一步；如果需要重做，请单独选择重跑。':'我会按照您选择的技能和明确提供的资料推进。需要补充信息时，会集中请您处理。'}</div>${t.chat.map(m=>`<div class="chat-line ${m.who}">${esc(m.text)}</div>`).join('')}</div><form class="detail-composer" onsubmit="event.preventDefault();sendChat('${t.id}',this.message.value)"><textarea name="message" ${locked?'disabled':''} placeholder="补充想法或资料说明；确认登记后才成为输入" required></textarea><button ${locked?'disabled':''}>发送</button></form><small>对话模型与技能执行模型分别选择；本 Demo 不调用模型。</small></section><section class="panel"><h3>当前产物</h3><small>目录：${esc(t.output)} · 不同周期独立保存</small>${t.files.map((f,i)=>`<div class="file-row"><span>${esc(f.name)}</span><button class="quiet" onclick="downloadResult('${t.id}',${i})">查看／下载</button></div>`).join('')||'<div class="empty">尚无当前结果。</div>'}<details><summary>已保留的旧结果 (${t.archives.length})</summary>${t.archives.map((f,i)=>`<div class="file-row"><span>${esc(f.name)}</span><button class="quiet" onclick="downloadResult('${t.id}',${i},true)">另存文件</button></div>`).join('')||'<small>未保留旧结果。</small>'}<small>另存不回滚进度、确认或后续执行。</small></details></section><section class="panel"><h3>执行记录</h3>${t.log.map(l=>`<div class="log-row"><small>${l.at}</small>${esc(l.text)}</div>`).join('')}<details><summary>读取证据 (${t.evidence.length})</summary>${t.evidence.map(e=>`<div class="log-row"><small>${e.at}</small>${esc(e.source)}<p>${esc(e.summary)}</p></div>`).join('')}</details></section></div><aside><section class="panel"><h3>执行步骤</h3>${t.steps.map((s,i)=>`<div class="step"><span class="step-index">${i+1}</span><div>${esc(s)}<small>输入：${(t.bindings[i]||['task']).map(v=>v==='task'?'任务共享输入':'第 '+(Number(v.split(':')[1])+1)+' 步输出').join('＋')}</small><small>${i<t.index?'已通过':i===t.index&&t.state!=='已完成'?t.state:'待执行'}</small></div>${i<t.index?'✓':''}</div>`).join('')}<div class="section-label">本次资料</div><p><small>需求资料：${t.input?'已提供':'缺失'}<br>原型：${t.optional?'已提供':t.optionalDecision?'人工同意仅处理文字':'待统一决定'}<br>Knowledge：${ws(t.ws).knowledge.map(esc).join('；')}</small></p>${t.group?`<div class="section-label">关联任务</div>${S.tasks.filter(x=>x.group===t.group&&x.id!==t.id).map(x=>`<p><button class="quiet" onclick="nav('detail','${x.id}')">${esc(x.title)}</button>${badge(x.state)}</p>`).join('')}`:''}</section><details class="simulation" open><summary>演示操作 · 模拟结果，不调用模型</summary><div class="actions"><button ${t.state!=='执行中'?'disabled':''} onclick="finishStep('${t.id}')">完成当前步骤</button><button ${t.state!=='执行中'?'disabled':''} onclick="finishStep('${t.id}','failure')">模拟失败</button><button ${t.state!=='执行中'?'disabled':''} onclick="finishStep('${t.id}','missing')">发现资料不足</button></div><small>点击后仅推进浏览器内演示状态，不代表真实业务执行。</small></details></aside></div>`}
function sendChat(id,text){const t=task(id);if(t.state==='已关闭')return;t.chat.push({who:'user',text});render();dialog('将补充内容登记为任务资料？',`<p>${esc(text)}</p><small>当前步骤执行中时不替换正在使用的输入；登记内容将在后续人工处理时使用。</small><div class="form-footer"><button onclick="modal.close()">仅保留对话</button><button class="primary" ${t.state==='执行中'?'disabled':''} onclick="task('${id}').input=true;message(task('${id}'),'人工确认登记Chat资料');modal.close();render()">确认登记</button></div>`)}
function showInbox(){const items=notices();dialog('待处理 · 集中提醒',items.length?items.map(n=>`<div class="inbox-row"><div><p>${esc(n.title)}</p><small>${esc(n.text)}<br>${n.task.ws} · ${n.task.planId?'第'+n.task.cycle+'周期 · ':''}${n.task.id}</small></div><button onclick="modal.close();nav('detail','${n.task.id}')">去处理</button></div>`).join(''):'<div class="empty">没有需要您介入的事项。普通运行和跳过周期记录不会逐条打扰。</div>')}
function showPlan(id){const p=plan(id);dialog('周期任务 · '+p.title,`<div class="preview-row"><span>计划状态</span>${badge(p.state)}</div><div class="preview-row"><span>规则</span>${p.rule} ${p.time}</div><div class="preview-row"><span>下次执行</span>${p.state==='周期进行中'&&p.next?fmt(p.next):'不再产生新周期'}</div><div class="preview-row"><span>未关闭执行</span>${pendingPlan(p).length}</div><div class="notice">主任务配置周期，成员不单独配置。上一周期整组关闭后才进入下一周期；错过不补跑。父计划本身不锁定技能／工作流。</div><div class="actions">${p.state==='已关闭'?'<small>计划已关闭，只读查看。</small>':`${p.state==='周期进行中'?`<button onclick="pausePlan('${id}')">暂停周期</button>`:p.state==='已暂停'?`<button onclick="resumePlan('${id}')">恢复周期</button>`:''}<button ${p.state!=='周期进行中'?'disabled':''} onclick="trigger(plan('${id}'),true);modal.close();render()">${p.auto?'演示本次触发':'人工生成本次执行'}</button><button onclick="editPlan('${id}')">修改后续计划</button><button onclick="expirePlan('${id}')">演示到期</button><button onclick="closePlan('${id}')">关闭整个周期任务</button>`}</div><div class="section-label">周期记录</div>${p.records.map(r=>`<div class="log-row"><small>${r.at}</small>${esc(r.text)}</div>`).join('')||'<small>尚无记录。</small>'}`)}
function pausePlan(id){dialog('暂停周期任务',`<p>默认仅暂停未来触发，本次子任务继续按原安排执行。</p><label class="choice"><input id="pause-current" type="checkbox"> 同时请求暂停当前执行（安全点生效）</label><div class="form-footer"><button onclick="showPlan('${id}')">取消</button><button class="primary" onclick="commitPausePlan('${id}')">确认暂停</button></div>`)}
function commitPausePlan(id){const p=plan(id);p.state='已暂停';if($('#pause-current').checked)pendingPlan(p).forEach(t=>requestPause(t.id));p.records.push({at:fmt(S.now),text:'人工暂停周期计划，未来不调度'});modal.close();render()}
function resumePlan(id){const p=plan(id);if(!ws(p.ws).enabled)return toast('请先启用工作区。');p.next=nextTime(p);if(!p.next)return expirePlan(id);p.state='周期进行中';p.records.push({at:fmt(S.now),text:'恢复，等待原规则下个未来时间，不补跑'});showPlan(id);render()}
function editPlan(id){const p=plan(id);dialog('修改后续计划',`<form onsubmit="event.preventDefault();const p=plan('${id}');p.time=this.time.value;p.end=this.end.value;p.next=nextTime(p);p.records.push({at:fmt(S.now),text:'调整后续时间；当前子任务配置不变'});modal.close();render()"><label class="field">执行时间<input type="time" name="time" value="${p.time}" required></label><label class="field">截止日期<input type="date" name="end" value="${p.end||''}"></label><small>仅影响未来周期，不改写当前执行和历史结果。</small><div class="form-footer"><button type="button" onclick="showPlan('${id}')">取消</button><button class="primary">保存后续计划</button></div></form>`)}
function expirePlan(id){const p=plan(id);if(p.state==='已关闭')return;p.state='已到期';p.next=null;p.records.push({at:fmt(S.now),text:'到期，停止新周期；剩余执行由人工处理'});modal.close();render();toast('已到期，仍有 '+pendingPlan(p).length+' 项未关闭；不自动关闭子任务。')}
function closePlan(id){const p=plan(id);if(pendingPlan(p).length)return toast('还有 '+pendingPlan(p).length+' 项子任务未关闭，请先人工处理。');dialog('关闭整个周期任务',`<p>将结束「${esc(p.title)}」的周期安排，保留所有历史和产物，关闭后只读。</p><div class="form-footer"><button onclick="showPlan('${id}')">取消</button><button class="primary" onclick="plan('${id}').state='已关闭';plan('${id}').next=null;modal.close();render()">确认关闭周期任务</button></div>`)}
function reschedule(id){const t=task(id);dialog('重新预约',`<form onsubmit="event.preventDefault();const t=task('${id}');const d=new Date(this.time.value);if(d<=S.now)return toast('请选择未来时间。');t.appointment=d;t.missed=false;message(t,'人工重新预约至 '+fmt(d));modal.close();render()"><label class="field">新预约时间<input type="datetime-local" name="time" required></label><div class="form-footer"><button class="primary">保存预约</button></div></form>`)}
function ackRecovery(id){const t=task(id);t.issue=null;t.state='待执行';message(t,'人工核实中断结果，默认重试本步；未自动重复不确定操作');render()}
function editWorkspace(id){const w=id?ws(id):{id:'',name:'',description:'',products:[],projects:[],knowledge:[],isDefault:false};if(id&&openTasks(id).length)return toast('未关闭实际执行锁定工作区，不能编辑。');dialog(id?'编辑工作区':'新建工作区',`<form onsubmit="event.preventDefault();saveWorkspace('${id||''}',this)"><div class="form-grid"><label class="field">工作区简称 *<input name="code" required maxlength="4" pattern="(?=.*[A-Z])[A-Z0-9]{1,4}" title="最多四位大写字母或数字，至少一个字母，不含符号" value="${esc(w.code||w.id)}"></label><label class="field">工作区名称 *<input name="name" required value="${esc(w.name)}"></label><label class="field full">工作区描述<textarea name="description">${esc(w.description)}</textarea></label><label class="field">覆盖产品<input name="products" value="${esc(w.products.join('、'))}" placeholder="多个名称用、或逗号分隔"><small>用户自行输入多个名称。</small></label><label class="field">覆盖项目<input name="projects" value="${esc(w.projects.join('、'))}" placeholder="多个名称用、或逗号分隔"></label><label class="field full">知识来源<textarea name="knowledge" placeholder="每行一个目录、文件或访问路径">${esc(w.knowledge.join('\n'))}</textarea><small>此 Demo 只展示路径，不访问真实文件系统。</small></label><label class="choice full"><input type="checkbox" name="default" ${w.isDefault?'checked':''}>设为默认工作区</label></div><div class="form-footer"><button type="button" onclick="modal.close()">取消</button><button class="primary">保存修改</button></div></form>`)}
function saveWorkspace(id,f){if(id&&openTasks(id).length)return toast('出现未关闭执行，不能保存。');const code=f.code.value.trim();if(!/^(?=.*[A-Z])[A-Z0-9]{1,4}$/.test(code))return toast('简称最多四位，仅允许大写字母和数字，且至少包含一个字母。');if(S.workspaces.some(w=>(w.code||w.id)===code&&w.id!==id))return toast('工作区简称重复。');let w=id?ws(id):null;if(!w){w={id:code,enabled:true};S.workspaces.push(w)}Object.assign(w,{code,name:f.name.value.trim(),description:f.description.value,products:f.products.value.split(/[、,，]/).map(x=>x.trim()).filter(Boolean),projects:f.projects.value.split(/[、,，]/).map(x=>x.trim()).filter(Boolean),knowledge:f.knowledge.value.split('\n').map(x=>x.trim()).filter(Boolean),isDefault:f.default.checked});if(w.isDefault)S.workspaces.forEach(x=>{if(x!==w)x.isDefault=false});modal.close();render();toast('工作区设置已保存，仅影响未来执行。')}
function toggleWorkspace(id){const w=ws(id);if(openTasks(id).length)return toast('有未关闭实际执行，不能停用工作区。');if(!w.enabled){w.enabled=true;S.plans.filter(p=>p.ws===id&&p.workspacePaused).forEach(p=>{p.workspacePaused=false;p.state='周期进行中';p.next=nextTime(p)});render();return toast('工作区已启用，等待未来计划，不补跑。')}dialog('暂时停用 '+w.name+'？',`<div class="notice">周期父计划本身不锁定工作区。停用将暂停该区后续预约与周期调度，不修改历史。</div><div class="form-footer"><button onclick="modal.close()">取消</button><button class="primary" onclick="commitDisableWorkspace('${id}')">确认停用</button></div>`)}
function commitDisableWorkspace(id){if(openTasks(id).length)return toast('已有未关闭执行，不能停用。');ws(id).enabled=false;S.plans.filter(p=>p.ws===id&&p.state==='周期进行中').forEach(p=>{p.workspacePaused=true;p.state='已暂停'});modal.close();render()}
function advance(minutes,offline=false){const previous=new Date(S.now);S.now=new Date(+S.now+minutes*60000);for(const p of S.plans){if(p.state==='已关闭')continue;if(p.end&&S.now>new Date(p.end+'T23:59:59')){p.state='已到期';p.next=null;p.records.push({at:fmt(S.now),text:'已到期；不自动结束已有子任务'});continue}if(p.state==='周期进行中'&&p.auto&&p.next&&p.next<=S.now){if(offline||S.pausedApp){p.records.push({at:fmt(S.now),text:'错过周期触发，不补跑、不生成积压子任务'})}else trigger(p);p.next=nextTime(p)}}for(const t of S.tasks){if(t.appointment&&t.appointment>previous&&t.appointment<=S.now&&t.state==='待执行'){if(offline||S.pausedApp){t.missed=true;message(t,'错过一次性预约，等待人工处理')}else start(t.id,false)}}modal.close();render();toast('演示时间：'+fmt(S.now))}
function simulateRestart(){S.pausedApp=false;for(const t of S.tasks.filter(t=>t.state==='执行中')){t.state='待确认';t.issue='interrupted';message(t,'重启尝试恢复：结果不确定，交人工核实，不自动重复执行')}modal.close();render();toast('演示恢复完成；不确定步骤集中待人工核实。')}
function demoTools(){dialog('演示控制 · 不代表真实后台运行',`<p>当前演示时间：<b class="mini-clock">${fmt(S.now)}</b></p><div class="notice">本页面只推演业务逻辑，不会在关机、关闭浏览器后继续执行，不调用模型或正式API。时间由您手动推进；刷新重置演示数据。</div><div class="actions"><button onclick="advance(10)">推进10分钟</button><button onclick="advance(1440)">推进一天</button><button onclick="advance(1440,true)">模拟离线一天</button><button onclick="simulateRestart()">模拟重启／不确定恢复</button><button onclick="S.pausedApp=true;modal.close();toast('模拟完全退出：调度停止；主窗口关闭与此不同。')">模拟完全退出</button></div><div class="section-label">直接推演计划</div>${S.plans.map(p=>`<div class="preview-row"><span>${esc(p.title)} · ${p.state}</span><button onclick="trigger(plan('${p.id}'));modal.close();render()">触发本周期</button></div>`).join('')}<div class="actions"><button onclick="showResources()">检查资源引用锁</button></div><small>可按顺序验证：资料不足→统一处理→执行→确认→完成→关闭；关联完成放行与周期关闭门槛；重跑保留／不保留；父计划暂停；周期错过及到期。</small>`)}
function flowUsers(name){return S.tasks.filter(t=>t.target===name&&t.state!=='已关闭')}
function showResources(){dialog('我的技能库 · Demo',`<p>选择已发布技能即可配置工作流，也可直接创建单技能任务。此处不修改正式技能包。</p>${availableSkills().map(s=>`<div class="preview-row"><div><b>${esc(s)}</b><small style="display:block">已发布 · 工作流可用</small></div><button onclick="modal.close();createTask();draft.targetType='技能';draft.target=skills[${skills.indexOf(s)}];taskForm()">用于新任务</button></div>`).join('')}<div class="form-footer"><button class="primary" onclick="showFlows()">配置工作流</button></div>`)}
function showFlows(){modal.close();nav('workflows')}
function workflowStatus(n){return flowInfo[n]?.enabled?'已启用':flowInfo[n]?.published?(flowInfo[n]?.everEnabled?'已停用':'待启用'):'草稿'}
function pageFlows(){const names=visibleFlows(),shown=names.filter(n=>(!flowSearch||(n+' '+(flowInfo[n]?.description||'')).includes(flowSearch))&&(flowFilter==='全部'||workflowStatus(n)===flowFilter));return `<div class="page-head"><div><span class="eyebrow">WORKFLOWS</span><h1>我的工作流</h1><p>把技能按工作顺序编排，让重复工作有条不紊地完成。</p></div><button class="primary" onclick="editFlow()">＋ 新建工作流</button></div><div class="role-strip"><span>当前角色 <b>${esc(currentRole)}</b> · 仅展示本角色和通用技能</span><details><summary>演示切换角色</summary><select aria-label="演示角色" onchange="currentRole=this.value;render()">${['测试工程师','运维工程师'].map(r=>`<option ${r===currentRole?'selected':''}>${r}</option>`).join('')}</select><small>仅模拟角色权限，不修改个人配置。</small></details></div><div class="flow-searchbar"><input class="search" aria-label="搜索工作流" placeholder="搜索工作流名称或描述…" value="${esc(flowSearch)}" oninput="flowSearch=this.value;updateFlowResults()"><div class="tabs">${['全部','已启用','待启用','已停用','草稿'].map(f=>`<button class="${flowFilter===f?'active':''}" onclick="flowFilter='${f}';render()">${f} <small>${f==='全部'?names.length:names.filter(n=>workflowStatus(n)===f).length}</small></button>`).join('')}</div></div><div id="flow-results">${flowCards(shown)}</div>`}
function updateFlowResults(){const names=visibleFlows().filter(n=>(!flowSearch||(n+' '+(flowInfo[n]?.description||'')).includes(flowSearch))&&(flowFilter==='全部'||workflowStatus(n)===flowFilter));$('#flow-results').innerHTML=flowCards(names)}
function flowCards(names){return names.length?`<div class="compact-flow-list">${names.map(n=>{const info=flowInfo[n],users=flowUsers(n),key=encodeURIComponent(n);return `<article class="compact-flow-card"><div class="compact-flow-top"><span class="flow-symbol">${esc(info.icon||'⑂')}</span><div class="compact-flow-title"><h2>${esc(n)}</h2><p>${esc(info.description||'暂无描述')}</p></div>${badge(workflowStatus(n))}<div class="actions"><button onclick="viewFlow(decodeURIComponent('${key}'))">查看</button><button ${info.enabled||users.length?'disabled':''} onclick="editFlow(decodeURIComponent('${key}'))">编辑</button><button ${info.enabled&&users.length?'disabled':''} onclick="toggleFlow(decodeURIComponent('${key}'))">${info.enabled?'停用':'启用'}</button><button ${info.enabled||users.length?'disabled':''} onclick="deleteFlow(decodeURIComponent('${key}'))">删除</button></div></div><div class="compact-chain">${flows[n].map((skill,i)=>`<span class="chain-node"><small>${i+1}</small>${esc(skill)}</span>${i<flows[n].length-1?'<span class="chain-arrow">→</span>':''}`).join('')}</div><div class="compact-flow-meta"><span>${flows[n].length} 个步骤 · ${esc(currentRole)} · 默认确认：${esc(info.defaultConfirmation||'人工确认')}（步骤可覆盖）</span><small>${users.length?users.length+' 个未关闭任务 · 不可编辑或停用':info.enabled?'已启用 · 任务可选':'未启用 · 任务不可选'}</small></div></article>`}).join('')}</div>`:'<div class="panel empty">暂无符合条件的工作流。点击「新建工作流」，从技能库开始编排。</div>'}
function viewFlow(n){const info=flowInfo[n],key=encodeURIComponent(n);dialog(n,`<p>${esc(info.description||'暂无描述')}</p><div class="preview-row"><span>状态</span>${badge(workflowStatus(n))}</div><div class="preview-row"><span>默认确认方式</span>${esc(info.defaultConfirmation||'人工确认')}</div><div class="preview-row"><span>特殊输入要求</span>${esc(info.inputRequirements||'使用技能原有输入要求')}</div>${flows[n].map((skill,i)=>`<section class="compact-view-step"><b>${i+1}. ${esc(skill)}</b><small>模型：${esc(info.settings?.[i]?.model||'使用技能设置')} · 确认：${esc(info.settings?.[i]?.confirm||'使用工作流设置')}</small><small>输入：${(info.bindings[i]||['task']).map(v=>v==='task'?'任务资料':'第 '+(Number(v.split(':')[1])+1)+' 步结果').join('＋')}</small><small>输出：${esc(info.settings?.[i]?.output||'使用技能原有输出要求')}</small></section>`).join('')}<div class="form-footer"><button onclick="editFlow(decodeURIComponent('${key}'),true)">创建副本</button>${info.enabled?`<button class="primary" onclick="modal.close();createTask();draft.target=decodeURIComponent('${key}');taskForm()">用于新任务</button>`:`<button class="primary" onclick="toggleFlow(decodeURIComponent('${key}'))">启用工作流</button>`}</div>`)}
function checkFlow(d){if(d.roles&&!d.roles.length)return '请至少选择一个适用角色。';if(d.roles&&d.roles.some(r=>d.steps.some(n=>skillRoles[n]!=='通用'&&(r==='通用'||skillRoles[n]!==r))))return '所选角色不能使用其中某些技能，请调整适用角色或技能。';if(!d.steps.length)return '请至少添加一个技能。';if(d.steps.some(n=>!availableSkills().includes(n)))return '包含当前角色不可用的技能，请重新选择。';if(d.bindings.some((b,i)=>!b.length||b.some(v=>v!=='task'&&(!/^step:\d+$/.test(v)||Number(v.split(':')[1])>=i))))return '请为每一步选择任务资料或前序结果，不能依赖本步或后续步骤。';return ''}
function toggleFlow(n){const info=flowInfo[n];if(info.enabled){if(flowUsers(n).length)return toast('有未关闭任务引用，不能停用。');dialog('停用工作流',`<p>停用「${esc(n)}」后，新任务不能再选择它。</p><div class="form-footer"><button onclick="modal.close()">取消</button><button class="primary" onclick="flowInfo[decodeURIComponent('${encodeURIComponent(n)}')].enabled=false;showFlows();toast('工作流已停用。')">确认停用</button></div>`);return}const problem=checkFlow({steps:flows[n],bindings:info.bindings,roles:info.roles||['测试工程师']});if(problem)return toast(problem);info.published=true;info.enabled=true;info.everEnabled=true;showFlows();toast('检查通过，工作流已启用，可在任务中选择。')}
const demoWorkflowModels=['演示模型 A','演示模型 B'];
function editFlow(name=null,copy=false){if(name&&!copy&&(flowUsers(name).length||flowInfo[name]?.enabled))return toast('先停用并关闭引用任务，或创建副本。');const info=flowInfo[name]||{};workflowDraft={original:copy?null:name,name:name?(copy?name+'（副本）':name):'',icon:info.icon||'⑂',roles:[...(info.roles||[currentRole])],description:info.description||'',inputRequirements:info.inputRequirements||'',defaultConfirmation:info.defaultConfirmation||'人工确认',steps:name?[...flows[name]]:[availableSkills()[0]],bindings:name?structuredClone(info.bindings):[['task']],settings:name?structuredClone(info.settings||flows[name].map(()=>({model:'使用技能设置',confirm:'使用工作流设置',output:''}))):[{model:'使用技能设置',confirm:'使用工作流设置',output:''}]};flowEditor()}
function captureFlow(){const f=$('#flow-form');if(!f)return;const d=workflowDraft;d.icon=f.elements.flowIcon.value;d.roles=[...f.querySelectorAll('[name=flowRole]:checked')].map(e=>e.value);for(const k of ['name','description','inputRequirements','defaultConfirmation'])d[k]=f.elements[{name:'flowName',description:'flowDescription',inputRequirements:'flowInput',defaultConfirmation:'flowConfirmation'}[k]].value;d.steps=d.steps.map((_,i)=>f.elements['skill'+i].value);d.bindings=d.steps.map((_,i)=>['task',...[...f.querySelectorAll('[name="binding'+i+'"]:checked')].map(x=>x.value)]);d.settings=d.steps.map((_,i)=>({model:f.elements['model'+i].value,confirm:f.elements['confirm'+i].value,output:f.elements['output'+i].value}))}
function flowEditor(){modal.close();S.page='flowedit';render()}
function flowEditorMarkup(){const d=workflowDraft;return `<div class="compact-editor-head"><button class="quiet" onclick="showFlows()">‹ 返回工作流</button><h1>${d.original?'编辑工作流':'新建工作流'}</h1><span>保存后默认停用</span></div><form id="flow-form" onsubmit="event.preventDefault();saveFlow(true)"><div id="flow-error" class="field-error" role="alert"></div><section class="compact-editor-basics"><label class="field full">图标<select name="flowIcon" style="width:100px">${['⑂','🧩','🔍','🧪','📋','📝','⚙️'].map(v=>`<option ${v===d.icon?'selected':''}>${v}</option>`).join('')}</select></label><div class="field full">适用角色 *<div class="choice">${['测试工程师','运维工程师','通用'].map(r=>`<label><input type="checkbox" name="flowRole" value="${r}" ${d.roles.includes(r)?'checked':''}>${r}</label>`).join('')}</div><small>通用表示所有角色可用；所选角色必须能使用流程中的每个技能。</small></div><label class="field">工作流名称 *<input name="flowName" value="${esc(d.name)}" required maxlength="64" placeholder="例如：需求评审与测试设计"></label><label class="field">默认步骤确认方式<select name="flowConfirmation">${['人工确认','自动继续'].map(v=>`<option ${v===d.defaultConfirmation?'selected':''}>${v}</option>`).join('')}</select></label><label class="field full">工作流描述<input name="flowDescription" value="${esc(d.description)}" placeholder="这套流程完成什么工作，适合什么场景"></label><label class="field full">特殊输入要求（可选）<textarea name="flowInput" rows="2" placeholder="不填写时使用各技能原有输入要求；实际资料在任务中提供。">${esc(d.inputRequirements)}</textarea></label></section><div class="compact-steps-heading"><h2>技能编排 <small>${d.steps.length} 个步骤</small></h2><span>${esc(currentRole)}与通用技能</span><button type="button" onclick="addFlowStep()">＋ 添加步骤</button></div><div class="compact-steps-labels"><span>顺序</span><span>执行技能</span><span>模型</span><span>确认方式</span><span>操作</span></div>${d.steps.map((skill,i)=>`<section class="compact-step"><div class="compact-step-row"><span class="step-order">${i+1}</span><select aria-label="第${i+1}步技能" name="skill${i}">${availableSkills().map(v=>`<option ${v===skill?'selected':''}>${esc(v)}</option>`).join('')}</select><select aria-label="第${i+1}步模型" name="model${i}">${['使用技能设置',...demoWorkflowModels].map(v=>`<option ${v===d.settings[i].model?'selected':''}>${v}</option>`).join('')}</select><select aria-label="第${i+1}步确认方式" name="confirm${i}">${['使用工作流设置','人工确认','自动继续'].map(v=>`<option ${v===d.settings[i].confirm?'selected':''}>${v}</option>`).join('')}</select><div class="step-controls"><button type="button" aria-label="上移第${i+1}步" ${i===0?'disabled':''} onclick="moveFlowStep(${i},-1)">↑</button><button type="button" aria-label="下移第${i+1}步" ${i===d.steps.length-1?'disabled':''} onclick="moveFlowStep(${i},1)">↓</button><button type="button" aria-label="移除第${i+1}步" ${d.steps.length===1?'disabled':''} onclick="removeFlowStep(${i})">×</button></div></div><div class="compact-step-extra">${i?`<label><input type="checkbox" name="binding${i}" value="step:${i-1}" ${(d.bindings[i]||[]).includes('step:'+(i-1))?'checked':''}> 使用上一步结果</label><small>同时保留任务资料及其他已选输入</small>`:'<small>首步使用任务提供的资料</small>'}<details><summary>输入与输出补充${d.settings[i].output?' · 已填写':''}</summary><div class="compact-extra-content">${i>1?`<div class="choice">其他前序结果：${Array.from({length:i-1},(_,j)=>`<label><input type="checkbox" name="binding${i}" value="step:${j}" ${(d.bindings[i]||[]).includes('step:'+j)?'checked':''}>第 ${j+1} 步</label>`).join('')}</div>`:''}<label class="field">本步特殊输出要求（可选）<textarea name="output${i}" rows="2" placeholder="不填写时使用技能原有输出要求。">${esc(d.settings[i].output)}</textarea></label><small>输入叠加不排他；补充要求不修改技能包，强制规则冲突交人工确认。</small></div></details></div></section>`).join('')}<div class="compact-editor-note">模型仅为演示选项，不调用服务。自动继续不绕过必需资料与冲突确认。配置检查不代表业务效果验证。</div><div class="compact-editor-footer"><button type="button" onclick="showFlows()">取消</button><button type="button" onclick="saveFlow(false)">保存草稿</button><button class="primary">检查并保存</button></div></form>`}
function addFlowStep(){captureFlow();workflowDraft.steps.push(availableSkills()[0]);workflowDraft.bindings.push(['task']);workflowDraft.settings.push({model:'使用技能设置',confirm:'使用工作流设置',output:''});flowEditor()}
function moveFlowStep(i,delta){captureFlow();const j=i+delta,d=workflowDraft;[d.steps[i],d.steps[j]]=[d.steps[j],d.steps[i]];[d.settings[i],d.settings[j]]=[d.settings[j],d.settings[i]];d.bindings=d.steps.map(()=>['task']);flowEditor();toast('顺序已调整，前序来源已清空，请重新核对。')}
function removeFlowStep(i){captureFlow();workflowDraft.steps.splice(i,1);workflowDraft.settings.splice(i,1);workflowDraft.bindings=workflowDraft.steps.map(()=>['task']);flowEditor();toast('步骤已移除，请重新核对前序来源。')}
function deleteFlow(n){if(flowInfo[n]?.enabled||flowUsers(n).length)return toast('已启用或有未关闭任务引用，不能删除。');const affected=S.plans.filter(p=>p.target===n&&p.state!=='已关闭');dialog('删除工作流 · 影响确认',`<p>确认删除「${esc(n)}」？已关闭任务的历史和产物继续保留。</p>${affected.length?`<div class="notice">以下周期计划将暂停后续调度，需要重新配置：${affected.map(p=>esc(p.title)).join('、')}</div>`:'<p>没有未关闭任务引用。</p>'}<div class="form-footer"><button onclick="modal.close()">取消</button><button class="primary" onclick="confirmDeleteFlow(decodeURIComponent('${encodeURIComponent(n)}'))">确认删除</button></div>`)}
function confirmDeleteFlow(n){if(flowInfo[n]?.enabled||flowUsers(n).length)return toast('引用情况已变化，不能删除。');S.plans.filter(p=>p.target===n&&p.state!=='已关闭').forEach(p=>{p.state='已暂停';p.next=null;p.resourceMissing=true;p.records.push({at:fmt(S.now),text:'工作流已删除，暂停后续调度，请重新配置'})});delete flows[n];delete flowInfo[n];showFlows();toast('工作流已删除，历史任务保持不变。')}
function saveFlow(publish){captureFlow();$('#flow-error').scrollIntoView({block:'center'});const d=workflowDraft,name=d.name.trim(),error=$('#flow-error');if(!name)return error.textContent='请填写工作流名称。';if(name!==d.original&&Object.hasOwn(flows,name))return error.textContent='工作流名称已存在。';if(d.original&&(flowUsers(d.original).length||flowInfo[d.original]?.enabled))return error.textContent='有未关闭任务引用，不能保存。';if(skills.includes(name))return error.textContent='工作流名称不能与技能名称相同。';if(publish&&checkFlow(d))return error.textContent=checkFlow(d);if(publish&&d.bindings.some((b,i)=>!b.length||b.some(x=>x!=='task'&&Number(x.split(':')[1])>=i)))return error.textContent='请为每一步选择任务输入或已存在的前序输出，不能依赖本步或后续。';if(d.original&&d.original!==name){S.plans.filter(p=>p.target===d.original).forEach(p=>p.target=name);delete flows[d.original];delete flowInfo[d.original]}flows[name]=[...d.steps];flowInfo[name]={published:publish,enabled:false,icon:d.icon,roles:[...d.roles],description:d.description.trim(),inputRequirements:d.inputRequirements.trim(),defaultConfirmation:d.defaultConfirmation,settings:structuredClone(d.settings),everEnabled:false,modified:fmt(S.now),bindings:structuredClone(d.bindings)};showFlows();toast(publish?'工作流已保存，默认停用。启用后可在任务中选择。':'草稿已保存，默认停用。')}
// Initial scenarios are deliberate prototype fixtures, never application data.
const first=makeTask({title:'门诊微信支付 · 需求分析与测试设计'});first.state='执行中';finishStep(first.id);const missing=makeTask({title:'住院结算 · 资料待补齐',input:false,optional:false});const ready=makeTask({title:'检验报告 · 需求评审',ws:'CIS',target:skills[0]});const booked=makeTask({title:'已错过预约 · 需求评审',target:skills[0]});booked.appointment=new Date(2026,10,19,8,0);booked.missed=true;
const daily=newPlan({title:'每日需求与测试检查',ws:'HIS',target:Object.keys(flows)[0],kind:'独立任务',auto:true,input:true,optional:true,rule:'每天',time:'09:00',start:'2026-11-19T00:00',end:'',weekdays:['1'],day:'1',monthFallback:'skip'});
const mixed=addGroup({ws:'CIS'});window.demoSnapshot=()=>structuredClone(S);render();
